ATTEMPT = re.compile(r"^ATTEMPT-[A-Z0-9-]{1,64}-(SUCCESS|FAIL-AFTER-CHECKPOINT|TIMEOUT)$")


class ValidationError(RuntimeError):
    pass


def require(condition: bool, message: str) -> None:
    if not condition:
        raise ValidationError(message)


def _pairs(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        require(key not in result, f"duplicate JSON key: {key}")
        result[key] = value
    return result


def canonical_bytes(value: Any) -> bytes:
    def walk(item: Any) -> None:
        if item is None or type(item) in (bool, int):
            return
        if type(item) is str:
            require(unicodedata.normalize("NFC", item) == item, "non-NFC string")
            return
        if type(item) is list:
            for child in item:
                walk(child)
            return
        require(type(item) is dict, f"unsupported JSON type: {type(item).__name__}")
        for key, child in item.items():
            require(type(key) is str and unicodedata.normalize("NFC", key) == key, "invalid JSON key")
            walk(child)
    walk(value)
    return json.dumps(value, ensure_ascii=False, allow_nan=False, sort_keys=True, separators=(",", ":")).encode()


def strict_json_bytes(raw: bytes, *, canonical: bool = False) -> Any:
    try:
        text = raw.decode("utf-8")
        require(unicodedata.normalize("NFC", text) == text, "JSON is not NFC")
        value = json.loads(text, object_pairs_hook=_pairs,
                           parse_float=lambda _: (_ for _ in ()).throw(ValidationError("floats forbidden")),
                           parse_constant=lambda _: (_ for _ in ()).throw(ValidationError("nonfinite forbidden")))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValidationError("invalid UTF-8 JSON") from exc
    if canonical:
        require(not raw.endswith((b"\n", b"\r")), "canonical JSON has final LF")
        require(canonical_bytes(value) == raw, "record is not canonical JSON")
    return value


def load_json(path: str, *, canonical: bool = False) -> Any:
    return strict_json_bytes((ROOT / path).read_bytes(), canonical=canonical)


def digest(raw: bytes) -> str:
    return hashlib.sha256(raw).hexdigest()


def parse_utc(value: Any) -> dt.datetime:
    require(type(value) is str and value.endswith("Z"), "timestamp must be UTC Z")
    try:
        result = dt.datetime.fromisoformat(value[:-1] + "+00:00")
    except ValueError as exc:
        raise ValidationError("invalid timestamp") from exc
    require(result.tzinfo == dt.timezone.utc, "timestamp is not UTC")
    return result


def validate_identity(value: Any, kind: str | None = None) -> str:
    require(type(value) is dict and set(value) == {"kind", "sha256", "value"}, "identity not closed")
    if kind is not None:
        require(value["kind"] == kind, f"identity kind must be {kind}")
    require(type(value["kind"]) is str and value["kind"], "identity kind absent")
    require(value["sha256"] == value["value"] and SHA.fullmatch(value["sha256"]) is not None,
            "identity digest closure failed")
    return value["sha256"]


def validate_root(record: dict[str, Any], schema: str) -> str:
    require(record.get("schema") == schema, f"expected {schema}")
    claimed = record.get("record_sha256")
    require(type(claimed) is str and SHA.fullmatch(claimed) is not None, "root digest invalid")
    preimage = dict(record); preimage.pop("record_sha256")
    require(digest(canonical_bytes(preimage)) == claimed, "root preimage digest mismatch")
    return claimed


def validate_nonroot(record: dict[str, Any], raw: bytes, schema: str) -> str:
    require(record.get("schema") == schema and "record_sha256" not in record, "non-root closure invalid")
    require(raw == canonical_bytes(record), "non-root bytes not canonical")
    return digest(raw)


def _schema_type_ok(value: Any, expected: str) -> bool:
    return {"object": type(value) is dict, "array": type(value) is list, "string": type(value) is str,
            "integer": type(value) is int, "boolean": type(value) is bool, "null": value is None}[expected]


def _resolve(ref: str, root: dict[str, Any]) -> Any:
    require(ref.startswith("#/$defs/"), f"external schema reference forbidden: {ref}")
    name = ref.rsplit("/", 1)[-1]
    require(name in root["$defs"], f"unknown schema ref: {ref}")
    return root["$defs"][name]


def _property_names(schema: Any, root: dict[str, Any]) -> set[str]:
    if not isinstance(schema, dict):
        return set()
    if "$ref" in schema:
        return _property_names(_resolve(schema["$ref"], root), root)
    names = set(schema.get("properties", {}))
    for child in schema.get("allOf", []):
        names.update(_property_names(child, root))
    return names


def validate_json_schema(value: Any, schema: dict[str, Any], root: dict[str, Any], path: str = "$") -> None:
    """Evaluate every JSON-Schema keyword used by the frozen evidence schema."""
    if "$ref" in schema:
        validate_json_schema(value, _resolve(schema["$ref"], root), root, path); return
    if "const" in schema:
        require(value == schema["const"], f"{path}: const mismatch")
    if "enum" in schema:
        require(value in schema["enum"], f"{path}: enum mismatch")
    if "type" in schema:
        choices = schema["type"] if isinstance(schema["type"], list) else [schema["type"]]
        require(any(_schema_type_ok(value, choice) for choice in choices), f"{path}: type mismatch")
    for child in schema.get("allOf", []):
        validate_json_schema(value, child, root, path)
    if "oneOf" in schema:
        matches = 0
        for child in schema["oneOf"]:
            try:
                validate_json_schema(value, child, root, path)
            except ValidationError:
                continue
            matches += 1
        require(matches == 1, f"{path}: oneOf matched {matches}")
    if "if" in schema:
        try:
            validate_json_schema(value, schema["if"], root, path); branch = schema.get("then")
        except ValidationError:
            branch = schema.get("else")
        if branch is not None:
            validate_json_schema(value, branch, root, path)
    if type(value) is dict:
        for key in schema.get("required", []): require(key in value, f"{path}: missing {key}")
        properties = schema.get("properties", {})
        for key, child in properties.items():
            if key in value: validate_json_schema(value[key], child, root, f"{path}.{key}")
        if schema.get("additionalProperties") is False:
            require(set(value) <= set(properties), f"{path}: additional properties")
        if schema.get("unevaluatedProperties") is False:
            require(set(value) <= _property_names(schema, root), f"{path}: unevaluated properties")
    if type(value) is list:
        require(len(value) >= schema.get("minItems", 0), f"{path}: too few items")
        require(len(value) <= schema.get("maxItems", len(value)), f"{path}: too many items")
        if schema.get("uniqueItems"):
            require(len({canonical_bytes(item) for item in value}) == len(value), f"{path}: duplicate item")
        for index, item in enumerate(value):
            if "items" in schema: validate_json_schema(item, schema["items"], root, f"{path}[{index}]")
    if type(value) is str:
        require(len(value) >= schema.get("minLength", 0), f"{path}: short string")
        require(len(value) <= schema.get("maxLength", len(value)), f"{path}: long string")
        if "pattern" in schema: require(re.search(schema["pattern"], value) is not None, f"{path}: pattern mismatch")
    if type(value) is int:
        require(value >= schema.get("minimum", value), f"{path}: below minimum")
        require(value <= schema.get("maximum", value), f"{path}: above maximum")


def validate_new_record(record: Any) -> None:
    schema = load_json(EVIDENCE_SCHEMA_PATH)
    validate_json_schema(record, schema, schema)
    record_schema = record.get("schema") if isinstance(record, dict) else None
    require(record_schema in NEW_SCHEMAS, "not one of the 18 closure records")
    if record_schema in ROOT_SCHEMAS: validate_root(record, record_schema)
    else: validate_nonroot(record, canonical_bytes(record), record_schema)


def _validate_object_receipt(receipt: Any) -> None:
    schema = load_json(EVIDENCE_SCHEMA_PATH)
    validate_json_schema(receipt, {"$ref": "#/$defs/object_receipt"}, schema)
    validate_identity(receipt["bucket_identity"], "aws_s3_bucket/v1")


def validate_launch_v3(record: Any) -> None:
    schema = load_json(EVIDENCE_SCHEMA_PATH)
    validate_json_schema(record, {"$ref": "#/$defs/launch_v3"}, schema)
    validate_root(record, "aws_c0_launch_request/v3")
    require((record["authority_id"], record["correction_authority_id"], record["closure_correction_authority_id"]) ==
            (AUTHORITY_ID, CORRECTION_ID, CLOSURE_AUTHORITY_ID), "authority IDs mismatch")
    require(record["zero_science_counters"] == ZERO, "zero-science counters mismatch")
    require(ATTEMPT.fullmatch(record["attempt_id"]) is not None, "unsupported attempt suffix")
    require(record["artifact_prefix"] == f"rehearsal/aws-c0/{record['rehearsal_id']}/{record['attempt_id']}/",
            "artifact prefix mismatch")
    kinds = load_json(CONTRACT_PATH)["identity_kind_by_field"]
    for field in ("attempt_identity", "preparation_packet_identity", "preparation_authorization_identity",
                  "authority_audit_identity", "static_validation_identity", "private_infrastructure_snapshot_identity",
                  "cost_model_identity", "closure_seed_identity"):
        validate_identity(record[field], kinds[field])
    for identity_field, receipt_field in (
        ("preparation_packet_identity", "preparation_packet_object"),
        ("preparation_authorization_identity", "preparation_authorization_object"),
        ("authority_audit_identity", "authority_audit_object"),
        ("static_validation_identity", "static_validation_object"),
        ("private_infrastructure_snapshot_identity", "private_infrastructure_snapshot_object"),
        ("cost_model_identity", "cost_model_object"), ("closure_seed_identity", "closure_seed_object"),
    ):
        _validate_object_receipt(record[receipt_field])
    timeouts = record["phase_timeouts_seconds"]
    require(timeouts["finalizer"] <= record["deployed_lambda_timeout_seconds"] <= 900,
            "finalizer exceeds Lambda timeout")
    require(timeouts["overall"] <= record["state_machine_timeout_seconds"], "workflow timeout too short")
    require(record["state_machine_timeout_seconds"] == load_json("aws/c0/state-machine/aws-c0.asl.json")["TimeoutSeconds"],
            "launch state-machine timeout differs from deployed definition")
    require(record["heartbeat_interval_seconds"] <= timeouts["heartbeat_stale"], "heartbeat budget unreachable")
    observed, attempt_deadline, cleanup_deadline = map(parse_utc,
        (record["observed_utc"], record["attempt_deadline_utc"], record["cleanup_deadline_utc"]))
    require(observed < attempt_deadline < cleanup_deadline, "deadline ordering invalid")
    require((cleanup_deadline - observed).total_seconds() <= timeouts["overall"], "overall timeout does not seal deadline")
    envelope = record["cost_envelope"]
    require(envelope["cost_model_identity"] == record["cost_model_identity"] and
            envelope["cost_model_object"] == record["cost_model_object"], "cost model binding mismatch")
    require(envelope["iam_pagination_bounds"] == record["iam_pagination_bounds"], "IAM bounds mismatch")
    require(envelope["resource_limits"]["lambda_duration_milliseconds"] >= timeouts["finalizer"] * 1000,
            "Lambda cost limit cannot reach finalizer")
    window = envelope["accounting_window"]
    require(parse_utc(window["start_inclusive_utc"]) <= observed and
            parse_utc(window["end_exclusive_utc"]) >= cleanup_deadline, "accounting window does not dominate run")


def validate_launch_v2(record: Any) -> None:
    require(isinstance(record, dict) and record.get("schema") == "aws_c0_launch_request/v3",
            "launch-v2 is obsolete")
    validate_launch_v3(record)


def validate_gate1_bootstrap_lineage_authority() -> None:
    contract = load_json("aws_c0_gate1_bootstrap_lineage_correction_contract.json")
    evidence_schema = load_json("aws_c0_gate1_bootstrap_lineage_correction_evidence_schema.json")
    path_manifest = load_json("aws_c0_gate1_bootstrap_lineage_correction_implementation_path_manifest.json")
    predecessor = load_json("aws_c0_gate1_bootstrap_lineage_correction_predecessor_manifest.json")
    validation = load_json("aws_c0_gate1_bootstrap_lineage_correction_validation_contract.json")
    authority = (ROOT / "AWS_C0_GATE1_BOOTSTRAP_LINEAGE_CORRECTION_AUTHORITY_AMENDMENT.md").read_text()

    records = (contract, path_manifest, predecessor, validation)
    require(all(item["authority_id"] == GATE1_BOOTSTRAP_LINEAGE_AUTHORITY_ID for item in records),
            "Gate1 lineage authority ID mismatch")
    require(contract["accepted_predecessor"] == {
                "commit": GATE1_ACCEPTED_BASE, "tree": GATE1_ACCEPTED_BASE_TREE},
            "Gate1 accepted predecessor mismatch")
    require(validation["accepted_base_commit"] == GATE1_ACCEPTED_BASE and
            validation["accepted_base_tree"] == GATE1_ACCEPTED_BASE_TREE and
            predecessor["accepted_base"] == contract["accepted_predecessor"],
            "Gate1 accepted predecessor is not cross-bound")

    expected_lineage = [{"kind": kind, "sha256": value}
                        for kind, value in GATE1_LINEAGE_IN_ORDER]
    require(validation["required_lineage_in_order"] == expected_lineage,
            "Gate1 validation lineage mismatch")
    require([(item["kind"], item["sha256"])
             for item in contract["exact_lineage_candidates_in_order"]] == list(GATE1_LINEAGE_IN_ORDER),
            "Gate1 contract lineage mismatch")
    require([(item["kind"], item["sha256"])
             for item in predecessor["successful_v5_plus_v6_lineage_in_order"]] == list(GATE1_LINEAGE_IN_ORDER),
            "Gate1 predecessor lineage mismatch")
    require(contract["diagnosis"]["failed_required_closure"] == GATE1_FAILED_V1_CLOSURE and
            predecessor["failed_historical_gate0_record"] | {"must_remain_historical_and_unmodified": False,
                                                               "satisfies_gate1": True} ==
            GATE1_FAILED_V1_CLOSURE | {"must_remain_historical_and_unmodified": False,
                                      "satisfies_gate1": True},
            "failed V1 closure is not preserved and rejected")
    sealed = validation["sealed_v6_closure_proof"]
    require(sealed == {
                "complete_byte_sha256": GATE1_LINEAGE_IN_ORDER[-1][1],
                "credentials_issued": True,
                "operator_session_renewal_disposition": "AWS_C0_OPERATOR_SESSION_RENEWAL_PASS",
                "predecessor_closure_sha256": GATE1_SEALED_V6_PREDECESSOR_SHA256,
                "schema": GATE1_LINEAGE_IN_ORDER[-1][0],
            }, "sealed V6 renewal proof mismatch")
    final_lineage = predecessor["successful_v5_plus_v6_lineage_in_order"][-1]
    require(final_lineage["credentials_issued"] is True and
            final_lineage["predecessor_closure_sha256"] == GATE1_SEALED_V6_PREDECESSOR_SHA256 and
            final_lineage["operator_session_renewal_disposition"] ==
            "AWS_C0_OPERATOR_SESSION_RENEWAL_PASS", "V6 renewal result is not sealed")

    require(contract["pre_live_record_kinds_in_order"] == list(GATE1_PRELIVE_RECORD_KINDS) and
            len(GATE1_PRELIVE_RECORD_KINDS) == 24, "Gate1 24-object kind sequence mismatch")
    arithmetic = contract["pre_live_arithmetic"]
    require(arithmetic["pre_live_total"] == 24 and
            arithmetic["pre_live_predecessor_object_receipts"] == 23 and
            validation["required_pre_live_arithmetic"] == {
                "object_count": 24, "predecessor_receipt_count": 23,
                "lineage_candidate_count": 6, "implementation_artifact_count": 8},
            "Gate1 24/23 arithmetic mismatch")
    statement = contract["preparation_authorization_statement"]
    required_statement = validation["required_preparation_authorization_statement"]
    require(statement["statement_version"] == GATE1_PREPARATION_STATEMENT_VERSION and
            statement["statement_template"] == GATE1_PREPARATION_STATEMENT_TEMPLATE and
            statement["preparation_packet_schema"] == "aws_c0_preparation_packet/v4" and
            statement["preparation_authorization_schema"] == "aws_c0_preparation_authorization/v3" and
            statement["pre_live_object_count_literal"] == 24 and
            statement["packet_locally_canonical_and_displayed_before_statement"] is True and
            statement["packet_published_before_statement"] is False and
            statement["statement_contains_packet_key_version_or_receipt"] is False and
            statement["packet_and_authorization_staged_only_after_statement"] is True and
            statement["preparation_only"] is True and
            statement["denied_actions_in_order"] ==
            ["LIVE_EXECUTION", "REPLAY", "DELETE", "TERMINATE", "SCIENTIFIC_EXECUTION"],
            "Gate1 preparation authorization V3 statement contract mismatch")
    require(re.findall(r"\{([a-z0-9_]+)\}", statement["statement_template"]) ==
            list(GATE1_PREPARATION_STATEMENT_PLACEHOLDERS),
            "Gate1 preparation authorization V3 placeholder order mismatch")
    require(required_statement == {
                "statement_version": GATE1_PREPARATION_STATEMENT_VERSION,
                "preparation_packet_schema": "aws_c0_preparation_packet/v4",
                "preparation_authorization_schema": "aws_c0_preparation_authorization/v3",
                "required_literal_bindings": [
                    "region=us-east-1", "instance_id=i-048bac00bdb540a4e",
                    "pre_live_object_count=24",
                    "allow=RECHECK_READ_ONLY_PREFLIGHT,APPLY_EXACT_IAM_REMEDIATION,"
                    "STAGE_EXACT_PRE_LIVE_OBJECTS,BOOTSTRAP_EXACT_STOPPED_INSTANCE,"
                    "CREATE_ONE_UNEXECUTED_CHANGE_SET,FINALIZE_EXACT_LIVE_PACKET",
                    "deny=LIVE_EXECUTION,REPLAY,DELETE,TERMINATE,SCIENTIFIC_EXECUTION",
                ],
                "required_placeholders_in_order": list(GATE1_PREPARATION_STATEMENT_PLACEHOLDERS),
            } and all(literal in GATE1_PREPARATION_STATEMENT_TEMPLATE
                      for literal in required_statement["required_literal_bindings"]) and
            "pre_live_object_count=21" not in GATE1_PREPARATION_STATEMENT_TEMPLATE,
            "Gate1 preparation authorization validation grammar mismatch")
    direct = [(item["from"], item["to"]) for item in contract["required_version_upgrades"]]
    transitive = [(item["from"], item["to"])
                  for item in contract["required_transitive_version_upgrades"]]
    require(direct == list(GATE1_DIRECT_VERSION_UPGRADES) and
            transitive == list(GATE1_TRANSITIVE_VERSION_UPGRADES),
            "Gate1 version upgrade map mismatch")
    require([{"from": old, "to": new} for old, new in GATE1_DIRECT_VERSION_UPGRADES] ==
            validation["required_version_upgrades"] and
            [{"from": old, "to": new} for old, new in GATE1_TRANSITIVE_VERSION_UPGRADES] ==
            validation["required_transitive_version_upgrades"],
            "Gate1 validation upgrade map mismatch")

    additions = path_manifest["authorized_current_outputs"]["paths_in_order"]
    modifications = path_manifest["authorized_current_modifications"]["paths_in_order"]
    require(additions == list(GATE1_BOOTSTRAP_LINEAGE_AUTHORITY_PATHS) and
            modifications == list(GATE1_BOOTSTRAP_LINEAGE_MODIFIED_PATHS) and
            path_manifest["complete_change_scope"] == {
                "added_path_count": 6, "modified_path_count": 6, "total_path_count": 12,
                "deletion_count": 0, "rename_count": 0,
                "unknown_addition_modification_deletion_or_rename": "REFUSE"},
            "Gate1 exact 6+6 path scope mismatch")
    require(path_manifest["explicitly_excluded_paths"] == list(GATE1_BOOTSTRAP_LINEAGE_EXCLUDED_PATHS),
            "Gate1 excluded path set mismatch")
    require(_git("rev-parse", f"{GATE1_CORRECTION_COMMIT}^{{tree}}") == GATE1_CORRECTION_TREE and
            subprocess.run(["git", "merge-base", "--is-ancestor", GATE1_CORRECTION_COMMIT, "HEAD"],
                           cwd=ROOT).returncode == 0,
            "approved Gate1 correction commit or tree mismatch")
    gate1_paths = set(filter(None, _git(
        "diff-tree", "--no-commit-id", "--name-only", "-r", GATE1_CORRECTION_COMMIT).splitlines()))
    require(gate1_paths == set(additions) | set(modifications),
            "approved Gate1 commit is not exactly 6 additions plus 6 modifications")

    for row in predecessor["critical_accepted_base_rows"]:
        path = row["path"]
        result = subprocess.run(["git", "show", f"{GATE1_ACCEPTED_BASE}:{path}"], cwd=ROOT,
                                stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        require(result.returncode == 0 and len(result.stdout) == row["bytes"] and
                digest(result.stdout) == row["sha256"], f"Gate1 predecessor bytes mismatch:{path}")
        listing = _git("ls-tree", GATE1_ACCEPTED_BASE, "--", path)
        require(listing == f'{row["mode"]} blob {row["git_blob"]}\t{path}',
                f"Gate1 predecessor Git identity mismatch:{path}")

    schema_defs = evidence_schema["$defs"]
    require(evidence_schema["additionalProperties"] is False and
            schema_defs["exact_pre_live_kinds"]["const"] == list(GATE1_PRELIVE_RECORD_KINDS) and
            schema_defs["exact_version_upgrades"]["const"] ==
            [{"from": old, "to": new} for old, new in GATE1_DIRECT_VERSION_UPGRADES] and
            schema_defs["exact_transitive_version_upgrades"]["const"] ==
            [{"from": old, "to": new} for old, new in GATE1_TRANSITIVE_VERSION_UPGRADES],
            "Gate1 evidence schema constants mismatch")
    prefix_items = schema_defs["exact_lineage_candidates"]["prefixItems"]
    schema_lineage: list[tuple[str, str]] = []
    for item in prefix_items:
        name = item["$ref"].rsplit("/", 1)[-1]
        properties = schema_defs[name]["allOf"][1]["properties"]["identity"]["properties"]
        require(properties["sha256"]["const"] == properties["value"]["const"],
                "Gate1 evidence identity value mismatch")
        schema_lineage.append((properties["kind"]["const"], properties["sha256"]["const"]))
    require(schema_lineage == list(GATE1_LINEAGE_IN_ORDER), "Gate1 evidence schema lineage mismatch")

    lane = validation["additive_runtime_negative_lane"]
    require(lane["historical_case_count"] == 352 and lane["correction_case_count"] == 6 and
            lane["total_case_count"] == 358 and
            lane["registry_schema"] == "aws_c0_static_negative_case_execution/v5" and
            [item["id"] for item in lane["cases_in_order"]] == list(GATE1_RUNTIME_NEGATIVE_CASE_IDS),
            "Gate1 additive negative lane mismatch")
    require(validation["positive_case_count"] == 12 and validation["negative_case_count"] == 20 and
            validation["total_case_count"] == 32 and
            validation["required_disposition"] ==
            "AWS_C0_GATE1_BOOTSTRAP_LINEAGE_CORRECTION_LOCAL_PASS",
            "Gate1 local validation arithmetic mismatch")
    require("AWS_C0_GATE1_BOOTSTRAP_LINEAGE_CORRECTION_AUTHORITY_CANDIDATE_COMPLETE" in authority and
            GATE1_LINEAGE_IN_ORDER[-1][1] in authority and
            GATE1_SEALED_V6_PREDECESSOR_SHA256 in authority,
            "Gate1 authority closure markers missing")


def paginate(pages: Iterable[dict[str, Any]], *, max_pages: int, max_items: int,
             item_fields: tuple[str, ...], token_field: str = "NextToken") -> tuple[list[Any], list[dict[str, Any]]]:
    require(type(max_pages) is int and max_pages > 0 and type(max_items) is int and max_items > 0,
            "pagination bounds invalid")
    items: list[Any] = []; transcript: list[dict[str, Any]] = []; incoming: str | None = None; seen: set[str] = set()
    for index, page in enumerate(pages):
        require(index < max_pages and type(page) is dict, "pagination page invalid")
        page_items: list[Any] = []
        for field in item_fields:
            require(type(page.get(field, [])) is list, f"page {field} invalid")
            page_items.extend(page.get(field, []))
        items.extend(page_items); require(len(items) <= max_items, "pagination item bound exceeded")
        outgoing = page.get(token_field)
        require(outgoing is None or (type(outgoing) is str and outgoing), "invalid token")
        require(outgoing not in seen, "repeated token")
        if outgoing is not None: seen.add(outgoing)
        transcript.append({"page_index": index,
                           "incoming_token_sha256": None if incoming is None else digest(incoming.encode()),
                           "outgoing_token_sha256": None if outgoing is None else digest(outgoing.encode()),
                           "item_count": len(page_items)})
        incoming = outgoing
        if outgoing is None: break
    require(transcript and incoming is None, "pagination did not terminate")
    return items, transcript


def compute_cost(cost_model: dict[str, Any], resource_use: dict[str, Any]) -> tuple[list[int], int]:
    contract = load_json(CONTRACT_PATH); dimensions = contract["resource_dimensions_in_order"]
    units = contract["resource_dimension_units"]
    require([r["dimension"] for r in cost_model["rates"]] == dimensions and
            [r["dimension"] for r in resource_use["dimensions"]] == dimensions, "dimension order mismatch")
    maximum = cost_model["integer_maximum"]
    require(maximum == 9007199254740991, "integer maximum mismatch")
    charges: list[int] = []
    for rate, usage in zip(cost_model["rates"], resource_use["dimensions"]):
        require(rate["unit"] == usage["unit"] == units[rate["dimension"]], "unit mismatch")
        charged, limit = usage["charged_units"], usage["limit_units"]
        require(type(charged) is int and 0 <= charged <= limit, "resource limit exceeded")
        numerator, denominator = rate["numerator_minor_units"], rate["denominator_units"]
        require(0 <= numerator <= maximum and 1 <= denominator <= maximum, "rate range invalid")
        product = charged * numerator
        require(product <= cost_model["product_maximum"] <= maximum, "product overflow")
        charges.append((product + denominator - 1) // denominator)
    total = cost_model["fixed_minor_units"] + sum(charges)
    require(total <= cost_model["total_maximum"] <= maximum, "total overflow")
    return charges, total


def validate_authorities() -> None:
    for path in AUTHORITY_PATHS: require((ROOT / path).is_file(), f"missing authority {path}")
    original, preparation, closure = (load_json(path) for path in VALIDATION_PATHS)
    require((len(original["positive_cases"]), len(original["negative_cases"])) == (18, 48), "66-case arithmetic")
    require((len(preparation["positive_cases"]), len(preparation["negative_cases"])) == (24, 60), "84-case arithmetic")
    require((len(closure["positive_cases"]), len(closure["negative_cases"])) == (36, 72), "108-case arithmetic")
    cases = [case for suite in (original, preparation, closure) for case in suite["positive_cases"] + suite["negative_cases"]]
    require(len(cases) == 258 and len({case.get("id", case.get("case_id")) for case in cases}) == 258,
            "case coordinates not 66+84+108")
    contract = load_json(CONTRACT_PATH)
    require(contract["new_record_schemas_in_chronological_order"] == list(NEW_SCHEMAS), "18-schema order mismatch")
