def _assert_expected_equals_observed(row: list[Any], observation: tuple[str, str, str]) -> None:
    """Compare frozen expectation after, never during, semantic evaluation."""
    require(observation == (row[17], row[18], row[19]), "expected equals observed mismatch")


def _record_literal_axis(axis_receipts: list[dict[str, Any]], member_receipts: list[dict[str, Any]],
                         row: list[Any], fixture: dict[str, Any], observation: tuple[str, str, str],
                         constructor: str, validator: str, predicate: str) -> None:
    actual, actual_code, actual_error = observation
    axis_receipts.append({"kind": "aws_c0_validation_axis_execution_receipt/v1", "axis_id": fixture["axis_id"],
                          "actual_disposition": actual, "actual_code": actual_code, "actual_refusal": actual_error,
                          "expected_disposition": row[17], "expected_code": row[18], "expected_refusal": row[19],
                          "constructor": constructor, "validator": validator, "predicate": predicate,
                          "operator": fixture["operation"], "zero_science_counters": dict(ZERO)})
    for member_order, member in enumerate(fixture["members"], 1):
        member_receipts.append({"axis_id": fixture["axis_id"], "member": member, "member_order": member_order,
                                "actual_disposition": actual, "actual_code": actual_code, "observation": actual_error,
                                "constructor": constructor, "validator": validator, "predicate": predicate})


def _validate_literal_registry_source(rows: list[list[Any]]) -> None:
    """G06: source-visible frozen leaves and direct ordered call edges only."""
    tree = ast.parse(Path(__file__).read_text(encoding="utf-8"))
    top_level = {node.name: node for node in tree.body if isinstance(node, ast.FunctionDef)}
    expected = {name for row in rows for name in row[9:12]}
    operators = {f"operate_axis_{index:04d}" for index in range(1, 879)}
    members = {f"member_axis_{index:04d}_{member_order}" for index, row in enumerate(rows, 1)
               for member_order in range(1, len(row[7]) + 1)}
    require(expected <= set(top_level) and operators <= set(top_level) and members <= set(top_level),
            "G06 literal source definitions missing")
    literal_nodes = [top_level[name] for name in expected | operators | members]
    require(not any(isinstance(node, ast.Lambda) for literal in literal_nodes for node in ast.walk(literal)),
            "G06 lambda or closure refuses")
    executor = top_level["execute_real_execution_registry"]
    calls = {node.func.id for node in ast.walk(executor) if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)}
    require(expected <= calls and members <= calls, "G06 direct literal callgraph incomplete")
    require(not any(isinstance(node, ast.Subscript) and isinstance(node.value, ast.Name) and node.value.id == "callables"
                    for node in ast.walk(executor)), "G06 dynamic callable funnel refuses")
    for name in expected:
        require(not any(isinstance(node, ast.Name) and node.id == "row" for node in ast.walk(top_level[name])),
                "G06 expected to observed dataflow refuses")


def execute_real_execution_registry() -> tuple[list[dict[str, Any]], list[dict[str, Any]], list[dict[str, Any]]]:
    """Execute every frozen local axis through its source-visible callable path."""
    contract = load_json(REGISTRY_PATH)
