def validate_real_execution_registry() -> None:
    execute_real_execution_registry()

# END LITERAL REGISTRY DEFINITIONS


def _git(*args: str, check: bool = True) -> str:
    result = subprocess.run(["git", *args], cwd=ROOT, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if check: require(result.returncode == 0, f"git {' '.join(args)} failed")
    return result.stdout.strip()


def validate_paths() -> None:
    require(_git("rev-parse", f"{EXPECTED_BASE}^{{tree}}") == EXPECTED_BASE_TREE, "accepted base tree mismatch")
    require(subprocess.run(["git", "merge-base", "--is-ancestor", EXPECTED_BASE, "HEAD"], cwd=ROOT).returncode == 0,
            "accepted base is not ancestor")
    if subprocess.run(["git", "cat-file", "-e", f"{REJECTED_DIAGNOSTIC}^{{commit}}"], cwd=ROOT,
                      stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode == 0:
        require(subprocess.run(["git", "merge-base", "--is-ancestor", REJECTED_DIAGNOSTIC, "HEAD"], cwd=ROOT).returncode != 0,
                "rejected diagnostic is ancestor")
    changed = set(filter(None, _git("diff", "--name-only", EXPECTED_BASE, "--").splitlines()))
    untracked = set(filter(None, _git("ls-files", "--others", "--exclude-standard").splitlines()))
    expected_paths = (set(IMPLEMENTATION_PATHS) | set(GATE0_CONTROL_PATHS) |
                      set(GATE1_BOOTSTRAP_LINEAGE_AUTHORITY_PATHS) |
                      set(LOCAL_DEPLOYMENT_READINESS_PATHS))
    require(
        changed | untracked == expected_paths,
        "path gate differs from the exact implementation, Gate 0, Gate 1, and local deployment-readiness paths",
    )
    readiness_changed = set(filter(None, _git(
        "diff", "--name-only", GATE1_CORRECTION_COMMIT, "--").splitlines()))
    require(readiness_changed | untracked == set(LOCAL_DEPLOYMENT_READINESS_PATHS),
            "local deployment-readiness checkpoint differs from its exact enumerated path set")
    # Python bytecode is an interpreter by-product, never candidate source;
    # git's tracked/untracked comparison above is the implementation scope.
    for path in (*IMPLEMENTATION_PATHS, *GATE0_CONTROL_PATHS,
                 *GATE1_BOOTSTRAP_LINEAGE_AUTHORITY_PATHS, *LOCAL_DEPLOYMENT_READINESS_PATHS):
        candidate = ROOT / path
        require(candidate.is_file() and not candidate.is_symlink() and stat.S_IMODE(candidate.stat().st_mode) == 0o644,
                f"{path} must be regular 100644")


def validate_fixture() -> None:
    validate_launch_v3(load_json("aws/c0/fixtures/launch-request.valid.json", canonical=True))
    fixture = load_json("aws/c0/fixtures/negative-cases.json", canonical=True)
    registry = load_json(REGISTRY_PATH)
    expected = sum((registry["exact_parent_case_ids_by_group_in_order"][g["group_id"]]
                    for g in registry["active_contract_groups_in_order"]), [])
    require(fixture == {"all_cases_executed": True,
                        "case_ids": expected + list(GATE1_RUNTIME_NEGATIVE_CASE_IDS),
                        "executed_case_count": 358,
                        "schema": "aws_c0_static_negative_case_execution/v5"},
            "case execution fixture mismatch")


def validate_sequence_authority() -> None:
    contract = load_json('aws_c0_deployment_sequence_correction_contract.json')
    previous = [new for _, new in GATE1_DIRECT_VERSION_UPGRADES + GATE1_TRANSITIVE_VERSION_UPGRADES]
    expected = {kind: kind.rsplit('/v', 1)[0] + '/v' + str(int(kind.rsplit('/v', 1)[1]) + 1) for kind in previous}
    expected['aws_c0_closure_seed/v1'] = 'aws_c0_closure_seed/v2'
    require(contract['version_upgrades'] == expected, 'sequencing upgrade map differs from exact directly affected stack')
    require(contract['pre_live_object_count'] == 24 and contract['pre_live_predecessor_count'] == 23 and
            contract['preparation_input_control_count'] == 6 and contract['predeployment_observed_control_count'] == 9 and
            contract['postdeployment_observed_control_count'] == 11 and
            contract['historical_records_modified'] is False and contract['aws_calls_authorized_by_this_correction'] is False,
            'sequencing arithmetic/history/scope changed')
    spec = importlib.util.spec_from_file_location('aws_c0_local_sequence_schema', ROOT / 'scripts/build_aws_c0_sequence_schema.py')
    builder = importlib.util.module_from_spec(spec); spec.loader.exec_module(builder)
    require(builder.build(ROOT) == load_json('aws_c0_deployment_sequence_evidence_schema.json'), 'new sequencing schema derivation drift')
    require(SEQUENCE_PRELIVE_RECORD_KINDS[8:14] == GATE1_PRELIVE_RECORD_KINDS[8:14], 'historical bootstrap/renewal kinds changed')


def validate_sources() -> None:
    validate_sequence_authority()
    for path in ("scripts/validate_aws_c0_static.py", "aws/c0/controller/ebu_c0_controller.py",
                 "aws/c0/finalizer/finalizer.py", "aws/c0/container/synthetic_worker.py",
                 "tests/aws/test_aws_c0_unattended_synthetic.py"):
        tree = ast.parse((ROOT / path).read_text(), filename=path)
        for node in ast.walk(tree):
            if isinstance(node, (ast.Import, ast.ImportFrom)):
                names = [a.name for a in node.names] if isinstance(node, ast.Import) else [node.module or ""]
                require(all(not n.startswith(("ebu_framework", "src.", "boto", "requests")) for n in names),
                        f"forbidden import in {path}")
    controller = (ROOT / "aws/c0/controller/ebu_c0_controller.py").read_text()
    finalizer = (ROOT / "aws/c0/finalizer/finalizer.py").read_text()
    controller_tree = ast.parse(controller)
    finalizer_tree = ast.parse(finalizer)
    controller_functions = {node.name: node for node in controller_tree.body if isinstance(node, ast.FunctionDef)}
    finalizer_functions = {node.name: node for node in finalizer_tree.body if isinstance(node, ast.FunctionDef)}
    def call_names(function: ast.FunctionDef) -> list[str]:
        return [
            node.func.id if isinstance(node.func, ast.Name) else node.func.attr
            if isinstance(node.func, ast.Attribute) else ""
            for node in ast.walk(function) if isinstance(node, ast.Call)
        ]
    require("prepare-request-v4" in controller and "aws_c0_start_receipt/v7" in controller,
            "controller current-record stack absent")
    require("aws_c0_source_sidecar/v5" in controller and "reserve_for_operation" in controller,
            "controller capture reservation absent")
    require("aws_c0_launch_request/v6" in controller and
            "aws_c0_live_packet/v6" in controller and
            "aws_c0_live_authorization/v6" in controller and
            "aws_c0_attempt_claim/v3" in controller,
            "controller Gate1 downstream version stack absent")
    require("FROZEN_PRELIVE_OBJECT_COUNT = 24" in finalizer and
            "FROZEN_PRELIVE_PREDECESSOR_COUNT = 23" in finalizer and
            all(kind in finalizer for kind in SEQUENCE_PRELIVE_RECORD_KINDS[8:]) and
            all(value in finalizer for _, value in GATE1_LINEAGE_IN_ORDER) and
            GATE1_SEALED_V6_PREDECESSOR_SHA256 in finalizer and
            "_validate_sealed_gate0_lineage_record" in finalizer and
            "AWS_C0_OPERATOR_BOOTSTRAP_PASS" in finalizer and
            "AWS_C0_OPERATOR_SESSION_RENEWAL_PASS" in finalizer,
            "finalizer Gate1 24/23 lineage stack absent")
    prepare_calls = call_names(controller_functions["prepare_request"])
    run_calls = call_names(controller_functions["run_attempt"])
    require(all(prepare_calls.count(name) == 0 for name in (
                "publish_and_readback_controller_journal", "build_controller_journal_handoff_v1",
                "publish_controller_journal_handoff")) and
            run_calls.count("publish_and_readback_controller_journal") == 1 and
            run_calls.count("build_controller_journal_handoff_v1") == 1 and
            run_calls.count("publish_controller_journal_handoff") == 1,
            "controller journal carrier lifecycle is not terminal-attempt scoped")
    run_source = ast.get_source_segment(controller, controller_functions["run_attempt"])
    require(run_source.index("if code != expected_exit or not terminal_seen") <
            run_source.index("publish_and_readback_controller_journal(") <
            run_source.index("build_controller_journal_handoff_v1(") <
            run_source.index("publish_controller_journal_handoff("),
            "controller terminal, journal, and carrier causal order is inverted")
    require("CaptureJournal" in finalizer and "failure envelope" in finalizer,
            "finalizer failure journal absent")
    closure_calls = call_names(finalizer_functions["closure"])
    require(closure_calls.count("_discover_controller_journal_handoff") == 1 and
            closure_calls.count("build_three_coordinate_capture_aggregate") == 1,
            "finalizer carrier discovery/aggregate callgraph is not exact")
    discovery_calls = call_names(finalizer_functions["_discover_controller_journal_handoff"])
    require(discovery_calls.count("_s3_version_entries") == 1 and
            discovery_calls.count("_aws_request") == 2,
            "finalizer carrier must perform one bounded List and two exact Gets")
    closure_source = ast.get_source_segment(finalizer, finalizer_functions["closure"])
    terminal_manifest_put = closure_source.index('"evidence/final-manifest"')
    require(closure_source.index("_discover_controller_journal_handoff(") <
            terminal_manifest_put <
            closure_source.index("publish_and_readback_finalizer_journal(") <
            closure_source.index("build_three_coordinate_capture_aggregate("),
            "carrier/controller Get, final-manifest Put, journal seal, and aggregate order is inverted")
    require("_put_record(" not in closure_source[terminal_manifest_put + 1:] and
            '"aws_c0_final_manifest_publication_observation/v4"' in closure_source[terminal_manifest_put:] and
            '"final_manifest_publication_observation_object": None' in closure_source[terminal_manifest_put:],
            "a substantive finalizer Put follows the designated terminal manifest Put")
    aggregate_assignment = next(node for node in finalizer_tree.body if isinstance(node, ast.Assign) and
                                any(isinstance(target, ast.Name) and
                                    target.id == "FINAL_CAPTURE_AGGREGATE_FIELDS" for target in node.targets))
    implemented_aggregate_fields = set(ast.literal_eval(aggregate_assignment.value))
    accepted_aggregate_fields = set(load_json(
        "aws_c0_audit_static_real_execution_registry_correction_evidence_schema.json"
    )["$defs"]["final_s3_capture_aggregate"]["required"])
    require(len(implemented_aggregate_fields) == 100 and
            implemented_aggregate_fields == accepted_aggregate_fields,
            "final capture aggregate does not match the accepted 100-field interface")
    require("controller_journal_version_id" in finalizer and
            "controller_publication_receipt_identity" in finalizer and
            "PUT_CONTROLLER_JOURNAL_HANDOFF" in finalizer,
            "finalizer does not bind the controller version and publication-receipt reference")
    require("aws_c0_capture_journal_publication_receipt/v1" in controller and
            "aws_c0_capture_journal_readback_receipt/v1" in controller and
            "aws_c0_closed_pointer_comparison_execution_receipt/v1" in controller,
            "controller carrier does not embed the accepted typed receipt interfaces")
    require("build_platform_smoke_known_case_local_binding" in controller and
            "platform-smoke-known-case-v1" in controller and
            "global_aggregate_payload_embedded" in controller,
            "first platform-smoke capsule local binding is absent")
    require("CONTROLLER_HANDOFF_COORDINATE_ROWS" in controller and
            "CONTROLLER_HANDOFF_COORDINATE_ROWS" in finalizer and
            "controller journal handoff fixed coordinate row refused" in finalizer,
            "finalizer does not enforce the fixed controller handoff table")
    require("ListObjectVersions" in finalizer and "ListObjectsV2" not in finalizer, "exact-version pagination absent")
    require("compute_cost" in finalizer and "COST_UNAVAILABLE" not in finalizer, "cost closure absent")
    template = load_json("aws/c0/cloudformation/aws-c0-unattended-synthetic.yaml")
    finalizer_statements = template["Resources"]["FinalizerRole"]["Properties"]["Policies"][0]["PolicyDocument"]["Statement"]
    by_sid = {statement.get("Sid"): statement for statement in finalizer_statements if isinstance(statement, dict)}
    state_machine = by_sid.get("ClosureReadExactStateMachine")
    executions = by_sid.get("ClosureReadSealedExecutionOnly")
    require(state_machine is not None and executions is not None, "Step Functions reads must be split by resource class")
    require(state_machine["Action"] == "states:DescribeStateMachine", "state-machine read is not exact")
    state_resource = state_machine["Resource"]["Fn::Sub"][0]
    require(":stateMachine:ebu-c0-closure-synthetic-v1" in state_resource and ":execution:" not in state_resource,
            "DescribeStateMachine has the wrong resource")
    require(executions["Action"] == ["states:DescribeExecution", "states:GetExecutionHistory"],
            "execution actions are incomplete or broadened")
    execution_resource = executions["Resource"]["Fn::Sub"]
    require(execution_resource == "arn:aws:states:us-east-1:${AWS::AccountId}:execution:ebu-c0-closure-synthetic-v1:*",
            "execution reads must use the sealed state-machine execution ARN namespace")
    parameters = template["Parameters"]
    require("ChangeSetArn" not in parameters and "StackArn" not in parameters and
            parameters.get("ExpectedChangeSetName") == {
                "Type": "String", "AllowedPattern": "^[A-Za-z][-A-Za-z0-9]{0,127}$"},
            "CloudFormation creation-time inputs require an unavailable future ARN")
    change_set = by_sid.get("ClosureReadChangeSet")
    stack = by_sid.get("ClosureReadStack")
    require(change_set is not None and
            change_set.get("Resource", {}).get("Fn::Sub") ==
            "arn:${AWS::Partition}:cloudformation:${AWS::Region}:${AWS::AccountId}:"
            "changeSet/${ExpectedChangeSetName}/*",
            "DescribeChangeSet is not scoped to the predetermined change-set name")
    require(stack is not None and
            stack.get("Resource", {}).get("Fn::Sub") ==
            "arn:${AWS::Partition}:cloudformation:${AWS::Region}:${AWS::AccountId}:"
            "stack/${AWS::StackName}/*",
            "stack reads are not scoped to the current stack name")
    cloudformation_read_actions = {
        "cloudformation:DescribeChangeSet", "cloudformation:GetTemplate",
        "cloudformation:DescribeStacks", "cloudformation:DescribeStackEvents",
    }
    expected_cloudformation_statements = {
        "ClosureReadChangeSet": {"cloudformation:DescribeChangeSet"},
        "ClosureReadStack": {
            "cloudformation:GetTemplate", "cloudformation:DescribeStacks",
            "cloudformation:DescribeStackEvents",
        },
    }
    for statement in finalizer_statements:
        actions = statement.get("Action", []) if isinstance(statement, dict) else []
        if isinstance(actions, str): actions = [actions]
        require(not ({"states:DescribeExecution", "states:GetExecutionHistory"} & set(actions)) or statement is executions,
                "execution read action appears outside sealed execution statement")
        cloudformation_actions = cloudformation_read_actions & set(actions)
        if cloudformation_actions:
            require(statement.get("Sid") in expected_cloudformation_statements and
                    set(actions) == expected_cloudformation_statements[statement["Sid"]] and
                    statement.get("Resource") != "*",
                    "CloudFormation read action appears outside its name-scoped statement")

    states = load_json("aws/c0/state-machine/aws-c0.asl.json")["States"]
    require(all("Retry" not in state for state in states.values()), "Retry forbidden")
    stops = [s for s in states.values() if s.get("Resource") == "arn:aws:states:::aws-sdk:ec2:stopInstances"]
    require(len(stops) == 1, "single StopInstances required")
    require(any(s.get("Parameters", {}).get("Payload", {}).get("action") == "safe_close" for s in states.values()), "safe close absent")
    compact = states.get("CompactPreflight")
    require(compact and compact.get("Type") == "Pass" and compact.get("ResultPath") == "$",
            "preflight response must be compacted before supervisor progression")
    compact_context = compact.get("Parameters", {}).get("context", {})
    expected_context = {"artifact_prefix.$", "attempt_identity.$", "attempt_deadline_utc.$",
                        "heartbeat_interval_seconds.$", "phase_timeouts_seconds.$",
                        "launch_request_object.$", "live_packet_object.$",
                        "live_authorization_object.$", "rehearsal_id.$", "attempt_id.$"}
    require(set(compact_context) == expected_context,
            "preflight compact projection carries an undeclared or missing field")
    preflight_projection = states["Preflight"].get("ResultSelector", {}).get("value", {})
    require(set(preflight_projection) == expected_context, "preflight retains a full Lambda response")
    serialized_states = canonical_bytes(states).decode()
    require(serialized_states.count("$.preflight.value") == len(compact_context),
            "full preflight response escapes compact projection")
    require(all("ResultPath" not in s or s.get("ResultPath") is None or "ResultSelector" in s or s["Type"] == "Pass"
                for s in states.values()), "AWS API task result is retained without a bounded selector")
    for name in ("DescribeBootState", "DescribeStopped", "DescribeSsmOnline", "GetSsmDelivery", "SendExactSsmHandoff", "PollAttempt"):
        require("ResultSelector" in states[name], f"{name} retains an unbounded AWS/Lambda response")
    require(STEP_FUNCTIONS_STATE_MAX_BYTES == 262144, "Step Functions state ceiling changed")


def write_output_atomic(path: Path, record: dict[str, Any]) -> None:
    """Create one canonical output, refusing an existing root or partial overwrite."""
    require(path.is_absolute() and path.parent.is_dir() and not path.exists(), "exclusive output path required")
    raw = canonical_bytes(record)
    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o644)
    try:
        os.write(fd, raw)
    finally:
        os.close(fd)


def _output_record(mode: str, parents: list[dict[str, Any]], axes: list[dict[str, Any]], members: list[dict[str, Any]]) -> dict[str, Any]:
    return {"schema": "aws_c0_static_validator_output/v4", "mode": mode, "result": "PASS",
            "parent_receipts": parents, "axis_receipts": axes, "member_execution_receipts": members,
            "outer_upgrade_receipts": [{"row": f"OB{i:02d}", "result": "PASS"} for i in range(10)],
            "journal_capture_budget_capability": {"producers_in_order": ["CONTROLLER", "FINALIZER"],
                                                  "maximum_envelopes": 512, "maximum_canonical_bytes": 1048576},
            "scientific_execution_authorized": False, "stage_f_execution_authorized": False,
            "zero_science_counters": dict(ZERO)}


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="offline AWS-C0 audit-v4/static-v4 validator")
    parser.add_argument("--mode", required=True, choices=("audit-v4", "static-v4"))
    parser.add_argument("--source", type=Path)
    parser.add_argument("--output", type=Path)
    parser.add_argument("--authority-audit-receipt", type=Path)
    parser.add_argument("--static-validation-receipt", type=Path)
    parser.add_argument("--provisional-put-observation", type=Path)
    args = parser.parse_args(argv); mode = args.mode
    # Programmatic no-output invocation remains the pure synthetic test API;
    # the public CLI requires a source, both cross-mode receipts, provisional
    # observation, and its exclusive output root.
    public = any(value is not None for value in (args.source, args.output, args.authority_audit_receipt,
                                                  args.static_validation_receipt, args.provisional_put_observation))
    if public:
        require(all(value is not None for value in (args.source, args.output, args.authority_audit_receipt,
                                                     args.static_validation_receipt, args.provisional_put_observation)),
                "ARG_MISSING")
        require(args.source.resolve() == ROOT.resolve() and args.source.is_dir(), "INPUT_CANONICAL_OR_PATH_REFUSED")
        for input_path in (args.authority_audit_receipt, args.static_validation_receipt, args.provisional_put_observation):
            require(input_path.is_file() and not input_path.is_symlink(), "INPUT_CANONICAL_OR_PATH_REFUSED")
    audit_lanes = (("accepted-authorities-and-active-groups", validate_authorities),
                   ("real-callable-registry-352-878-1108", validate_real_execution_registry),
                   ("exact-base-and-14-path-scope", validate_paths))
    static_lanes = audit_lanes + (("canonical-fixtures", validate_fixture), ("source-ast-and-runtime-capabilities", validate_sources))
    lanes = audit_lanes if mode == "audit-v4" else static_lanes
    results: list[dict[str, str]] = []
    try:
        for name, function in lanes:
            function(); results.append({"lane": name, "result": "PASS"})
    except (ValidationError, OSError, ValueError, SyntaxError) as exc:
        results.append({"lane": name, "result": "FAIL", "detail": str(exc)})
        return 1
    if public:
        parents, axes, members = execute_real_execution_registry()
        output = _output_record(mode, parents, axes, members); output["lanes"] = results
        try:
            write_output_atomic(args.output, output)
        except (ValidationError, OSError):
            return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
